import { GoogleAuthProvider, getAuth, signInWithPopup } from 'firebase/auth';
import { useDispatch } from 'react-redux';
import { signInSuccess } from '/src/redux/user/userSlice.js';
import { app } from '../../../firebase';
import { useNavigate } from 'react-router-dom';

export default function OAuth() {
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const handleGoogleClick = async () => {
    try {
      const provider = new GoogleAuthProvider();
      const auth = getAuth(app);

      const result = await signInWithPopup(auth, provider);

      const res = await fetch('/api/auth/google', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          name: result.user.displayName,
          email: result.user.email,
          photo: result.user.photoURL,
        }),
      });
      const data = await res.json();
      dispatch(signInSuccess(data));
      navigate('/');
    } catch (error) {
      console.log('could not sign in with google', error.message);
    }
  };
  return (
    <button
      onClick={handleGoogleClick}
      type='button'
      className='mt-4 flex items-center justify-center p-3 rounded-md shadow-md hover:shadow-lg'
      style={{
        backgroundColor: '#FFFFFF',
        backgroundImage: 'url(data:image/svg+xml;base64,)',
        backgroundRepeat: 'no-repeat',
        backgroundPosition: '12px center',
        backgroundSize: '18px',
        border: '1px solid #ddd',
        boxShadow: '0 0 20px 0 rgba(0, 0, 0, 0.2), 0 5px 5px 0 rgba(0, 0, 0, 0.24)',
        paddingLeft: '40px',
        transition: 'background-color .3s, box-shadow .3s',
        cursor: 'pointer',
        fontSize: '14px',
        fontWeight: 500,
        fontFamily: '"Segoe UI",Roboto,sans-serif',
      }}
    > 
      SIGN IN WITH GOOGLE
    </button>
  );
}